Full `seg.c` as promised in the post (sha256 fbaf6f6dcd8c50e0fc911f98561bcdaa9e9326205fca3e2c7c9c85e8ee485145). It was built against nauty 2.8.9 (tarball sha256 c97ab42bf48796a86a598bce3e9269047ca2b32c14fc23e07208a244fe52c4ee).

Two points the post left implicit:
- **The induction chain.** p ≤ 23 was searched in full. The pruning at p=25 rests on every tree of order 23 being SEG. The pruning at p=27 rests on every tree of order 25 being SEG, including the 101,748,748 trees that were themselves settled by the lemma.
- **Why the twin-free counts are a fair cross-check.** The `lc[v]>=2` test (some vertex has two leaf neighbours) is the complement of A002988's class. Run on gentreeg output for n = 1..18, a separate counter gives 1, 1, 0, 1, 1, 2, 3, 6, 10, 21, 39, 82, 167, 360, 766, 1692, 3726, 8370. That matches the A002988 table term for term, including a(2)=1, the single edge, where each leaf is the other's only neighbour.

```c
/* SEG check for odd-order trees from gentreeg via OUTPROC. p=2k+1, q=2k.
   Edge labels bijection onto {+-1..+-k}; vertex sums bijection onto {-k..k}. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#define MX 64
static int P,K,Q, eu[MX],ev[MX], lab[MX], sum[MX], deg[MX], inc[MX][MX];
static long long ntrees=0, nls=0, ndfs=0, nfail=0, nodes_max=0; static long long hist[40];
static int counting=-1, dfsfirst=0, reduce_=0; static long long nskip=0; static long long totcount=0, mincount=-1; 
static uint64_t rng=88172645463325252ULL;
static inline uint64_t xr(void){rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;return rng;}
static int verify(void){
  int s[MX]={0}, seenL[2*MX+1]={0}, seenS[2*MX+1]={0};
  for(int e=0;e<Q;e++){int L=lab[e]; if(L==0||L<-K||L>K) return 0; if(seenL[L+MX]++) return 0; s[eu[e]]+=L; s[ev[e]]+=L;}
  for(int v=0;v<P;v++){ if(s[v]<-K||s[v]>K) return 0; if(seenS[s[v]+MX]++) return 0; }
  return 1;
}
static int intv[MX], NI; static unsigned NOISE=3; static int ccnt[2*MX+1]; static int oor, cst;
static inline void rmv(int v){ int s=sum[v]; if(s<-K||s>K){oor--;cst--;} else { if(ccnt[s+MX]>1) cst--; ccnt[s+MX]--; } }
static inline void addv(int v){ int s=sum[v]; if(s<-K||s>K){oor++;cst++;} else { if(ccnt[s+MX]>0) cst++; ccnt[s+MX]++; } }
long long lsiters=0;
static int localsearch(long long maxit){
  int L[MX]; int m=0; for(int i=1;i<=K;i++){L[m++]=i;L[m++]=-i;}
  for(int i=Q-1;i>0;i--){int j=xr()%(i+1); int t=L[i];L[i]=L[j];L[j]=t;}
  for(int e=0;e<Q;e++) lab[e]=L[e];
  for(int v=0;v<P;v++) sum[v]=0; for(int e=0;e<Q;e++){sum[eu[e]]+=lab[e]; sum[ev[e]]+=lab[e];}
  for(int i=0;i<=2*MX;i++) ccnt[i]=0; oor=0; cst=0; for(int v=0;v<P;v++) addv(v);
  long long it;
  for(it=0; it<maxit && cst>0; it++){
    int a,b; uint64_t R=xr();
    { int w=-1; int o=(int)(((R&0xffff)*NI)>>16);
      for(int t=0;t<NI;t++){ int x=intv[o]; if(++o==NI) o=0; int sx=sum[x]; if(sx<-K||sx>K||ccnt[sx+MX]>1){w=x;break;} }
      a=inc[w][(((R>>16)&0xffff)*deg[w])>>16]; }
    b=(int)((((R>>32)&0xffff)*Q)>>16); if(a==b) continue;
    int d=lab[b]-lab[a];
    int vs[4]={eu[a],ev[a],eu[b],ev[b]}; int nv=0, uv[4];
    for(int t=0;t<4;t++){int w=vs[t],dup=0; for(int r=0;r<nv;r++) if(uv[r]==w) dup=1; if(!dup) uv[nv++]=w;}
    int c0=cst;
    for(int t=0;t<nv;t++) rmv(uv[t]);
    lab[a]+=d; lab[b]-=d; sum[eu[a]]+=d; sum[ev[a]]+=d; sum[eu[b]]-=d; sum[ev[b]]-=d;
    for(int t=0;t<nv;t++) addv(uv[t]);
    if(cst<=c0 || ((R>>48)%1000)<NOISE) continue;
    for(int t=0;t<nv;t++) rmv(uv[t]);
    lab[a]-=d; lab[b]+=d; sum[eu[a]]-=d; sum[ev[a]]-=d; sum[eu[b]]+=d; sum[ev[b]]+=d;
    for(int t=0;t<nv;t++) addv(uv[t]);
  }
  lsiters+=it; return cst==0;
}
static int ord[MX];
static int usedL[2*MX+1], usedS[2*MX+1], psum[MX], rem[MX]; static long long nodes;
static int dfs(int i){
  nodes++;
  if(i==Q){ if(counting>=0){ totcount++; return 0;} return 1; }
  int e=ord[i];
  for(int L=-K; L<=K; L++){ if(!L||usedL[L+MX]) continue;
    if(i==0 && L<0 && counting<0) continue; /* negation symmetry */
    int u=eu[e],v=ev[e];
    psum[u]+=L; psum[v]+=L; rem[u]--; rem[v]--;
    int ok=1, done[2]={-1,-1}, nd=0; int ww[2]={u,v};
    for(int t=0;t<2;t++){int w=ww[t]; if(rem[w]==0){ int s=psum[w]; if(s<-K||s>K||usedS[s+MX]) {ok=0;} else {usedS[s+MX]=1; done[nd++]=w;} } if(!ok) break;}
    if(ok){ usedL[L+MX]=1; lab[e]=L; int r=dfs(i+1); usedL[L+MX]=0; if(r){ for(int t=0;t<nd;t++) usedS[psum[done[t]]+MX]=0; psum[u]-=L; psum[v]-=L; rem[u]++; rem[v]++; return 1;} }
    for(int t=0;t<nd;t++) usedS[psum[done[t]]+MX]=0;
    psum[u]-=L; psum[v]-=L; rem[u]++; rem[v]++;
  }
  return 0;
}
static int exact(int *vpar){
  int i=0; for(int j=P;j>=2;j--) ord[i++]=j-2;  /* children before parents */
  memset(usedL,0,sizeof usedL); memset(usedS,0,sizeof usedS);
  for(int v=0;v<P;v++){psum[v]=0; rem[v]=deg[v];}
  nodes=0; int r=dfs(0); if(nodes>nodes_max) nodes_max=nodes; return r;
}
static FILE *hardf=NULL;
void segproc(FILE *f, int *vpar, int n){
  P=n; K=(n-1)/2; Q=n-1; ntrees++;
  for(int v=0;v<n;v++) deg[v]=0;
  for(int j=2;j<=n;j++){int e=j-2; eu[e]=j-1; ev[e]=vpar[j]-1; inc[eu[e]][deg[eu[e]]++]=e; inc[ev[e]][deg[ev[e]]++]=e;}
  NI=0; for(int v=0;v<n;v++) if(deg[v]>1) intv[NI++]=v;
  if(reduce_){ int lc[MX]={0}; for(int e=0;e<Q;e++){ if(deg[eu[e]]==1) lc[ev[e]]++; if(deg[ev[e]]==1) lc[eu[e]]++; }
    for(int v=0;v<n;v++) if(lc[v]>=2){ nskip++; return; } }
  int tries; for(tries=0;tries<4;tries++){ if(localsearch(200000LL<<(2*tries))) break; }
  int ok;
  if(tries<4){ nls++; hist[tries]++; ok=verify(); if(!ok){fprintf(stderr,"VERIFYFAIL LS\n"); exit(2);} }
  else { ndfs++; ok=exact(vpar); if(ok&&!verify()){fprintf(stderr,"VERIFYFAIL DFS\n"); exit(2);} }
  if(!ok){ nfail++; fprintf(stderr,"NOSEG n=%d:",n); for(int j=2;j<=n;j++) fprintf(stderr," %d",vpar[j]); fprintf(stderr,"\n"); }
}
```

